#!/usr/bin/env node
import path from 'node:path'

import { Arg, Cli, Cmd } from '../../api/src/cli/index.ts'

import { formatProblems, validate } from './validate.ts'
import type { Project } from '../src/index.ts'
import * as Load from './load.ts'

/** Docker commands that tear down, and so run in reverse dependency order. */
const REVERSED = new Set(['down', 'stop', 'kill', 'rm'])

/** What the root options hand to every subcommand. */
type Shared = { config?: string; stack?: string[] }

const config = Arg.string('config', {
  alias: 'c',
  description: 'Config file (default: the nearest stack.config.ts)',
  complete: 'file',
})

const stack = Arg.array(Arg.string(), 'stack', {
  alias: 's',
  description: 'Limit to one stack, repeatable (default: all, in dependency order)',
})

/** Load the config named by the root options and pick the stacks it applies to. */
const resolve = async (shared: Shared): Promise<{ project: Project; names: string[]; dir: string }> => {
  const file = Load.find(shared.config)
  const project = await Load.load(file)

  for (const name of shared.stack ?? []) {
    if (!(name in project.specs)) throw new Error(`unknown stack "${name}" — have: ${project.order.join(', ')}`)
  }

  const names = shared.stack?.length ? project.order.filter((name) => shared.stack!.includes(name)) : project.order
  // Relative paths in a spec — bind mounts, secret files — are written against the config.
  return { project, names, dir: path.dirname(file) }
}

/** Report reference problems on stderr; returns the number of hard errors. */
const report = (project: Project, names: string[], only: 'errors' | 'all'): number => {
  let errors = 0

  for (const name of names) {
    const problems = validate(project.specs[name]!)
    const shown = only === 'all' ? problems : problems.filter((problem) => problem.level === 'error')

    if (shown.length > 0) process.stderr.write(`${formatProblems(shown, `[${name}]`)}\n`)
    errors += problems.filter((problem) => problem.level === 'error').length
  }

  return errors
}

const build = Cmd.build('build')
  .describe('Write the generated compose files')
  .arg(
    Arg.string('dir', {
      alias: 'd',
      description: 'Directory to write into (default: the working directory)',
      complete: 'dir',
    }),
  )
  .context<Shared>()
  .handle(async (input, shared) => {
    const { project, names } = await resolve(shared)

    for (const name of names) {
      const file = path.resolve(input.dir ?? process.cwd(), `compose.${name}.json`)
      await Load.write(project.specs[name]!, file)

      const shown = path.relative(process.cwd(), file)
      process.stdout.write(`${shown.startsWith('..') ? file : shown}\n`)
    }

    // The files are written either way — a report is more useful than a refusal.
    if (report(project, names, 'all') > 0) process.exitCode = 1
  })

const compose = Cmd.build('compose')
  .describe('Alias for `docker compose`, with the generated file supplied on stdin')
  .use('ship compose [options] <docker args...>')
  .arg(Arg.array(Arg.string(), 'args', { positional: true, description: 'Passed through to `docker compose`' }))
  .context<Shared>()
  .handle(async (input, shared) => {
    const args = input.args ?? []
    if (args.length === 0) throw new Error('nothing to run — try `ship compose up -d`')

    const { project, names, dir } = await resolve(shared)
    const command = args[0]!
    const tearingDown = REVERSED.has(command)
    // Bringing up follows the dependency order; tearing down undoes it.
    const ordered = tearingDown ? [...names].reverse() : names

    if (!tearingDown && report(project, names, 'errors') > 0) {
      throw new Error('the generated file has undeclared references — `ship build` reports them in full')
    }

    for (const name of ordered) {
      const argv = [
        'compose',
        '--project-name',
        project.projects[name]!,
        '--project-directory',
        dir,
        '-f',
        '-',
        ...args,
      ]
      const code = await Load.docker(argv, project.specs[name]!, command)

      if (code !== 0) {
        process.exitCode = code
        // Keep tearing down the rest; stop at the first failure for anything else.
        if (!tearingDown) return
      }
    }
  })

const root = Cmd.build('ship').describe('Typed docker compose stacks').option(config, stack).with(build, compose)

/**
 * Hand everything after `compose` to docker verbatim.
 *
 * The parser claims every flag it recognises and rejects the rest, so `-d` would never survive
 * the trip. Walking argv the way `route` does and inserting the terminator where `compose` was
 * found turns the whole tail into operands — ship's own options go ahead of the command, which
 * is where `route` already accepts them.
 */
const passthrough = (argv: string[]): string[] => {
  let cmd: Cmd.Node = root

  for (let index = 0; index < argv.length; index++) {
    const token = argv[index]!
    if (token === '--') break

    if (token.startsWith('-') && token.length > 1) {
      const long = token.startsWith('--')
      const [body = '', inline] = token.replace(/^--?/, '').split('=')
      const arg = cmd.lookup(long ? body : body[0]!)
      // `-sapp` and `--stack=app` carry their own value; `-s app` spends the next token.
      const bundled = !long && body.length > 1
      if (arg && !arg.boolean() && inline === undefined && !bundled) index += 1
      continue
    }

    const next = cmd.find(token)
    if (!next) break

    cmd = next
    if (cmd !== compose) continue

    const tail = argv.slice(index + 1)
    // A leading `--help` is still ship's; `ship compose -- --help` asks docker for its own.
    if (tail.length === 0 || tail[0] === '--help' || tail[0] === '-h') break

    return [...argv.slice(0, index + 1), '--', ...tail]
  }

  return argv
}

const main = async (): Promise<void> => {
  const code = await Cli.run(root, passthrough(process.argv.slice(2)))
  // A handler may already have reported docker's own exit code.
  if (code !== 0) process.exitCode = code
}

main().catch((error: unknown) => {
  process.stderr.write(`error: ${error instanceof Error ? error.message : String(error)}\n`)
  process.exitCode = 1
})
